    'الاقتراحات من الذكاء الاصطناعي ولازم توافق على كل نقلة. مفيش حاجة بتتنفذ لوحدها.' => 'Suggestions come from AI and every move needs your approval. Nothing runs on its own.',
    'نسبة الضغط (CTR): من كل 100 مرة إعلانك ظهر، كام مرة حد ضغط عليه. متوسط حملاتك: %s. أعلى = إعلانك بيشد أكتر.' => 'CTR: out of every 100 times your ad was shown, how many got a click. Your average: %s. Higher means a more compelling ad.',
    'تكلفة الضغطة (CPC): بتدفع كام في المتوسط عشان حد يضغط. متوسط حملاتك بعملة %s: %s. أقل = أحسن.' => 'CPC: what you pay on average per click. Your average %s: %s. Lower is better.',
    'تكلفة الألف ظهور (CPM): بتدفع كام عشان إعلانك يظهر 1000 مرة. بتقيس غلاء الجمهور، مش جودة الإعلان.' => 'CPM: what 1,000 impressions cost you. It measures how expensive the audience is, not ad quality.',
    'تكلفة النتيجة: الصرف ÷ النتايج (شراء، رسالة، تفاعل حسب هدف الحملة). ده أهم رقم لو هدفك مبيعات.' => 'Cost per result: spend ÷ results (purchase, message or engagement depending on the goal). The key number if your goal is sales.',
