    'كل خطة = خطوات بأيام. الإيميل بيتبعت لوحده من SMTP بتاعك (من التكاملات). الواتساب والمكالمة بيبقوا مهمة للمسؤول في يومها، وضغطة واحدة بتفتح واتساب والرسالة جاهزة. الخطة بتقف لوحدها لما العميل يبقى "بقى عميل" أو "مش مناسب". استخدم {name} و{company} و{me}.' => 'Each plan is a set of steps by day. Emails are sent automatically from your SMTP (in Integrations). WhatsApp and calls become a task for the owner on their day, and one click opens WhatsApp with the message ready. The plan stops by itself when the lead becomes "Won" or "Not a fit". Use {name}, {company} and {me}.',
