    'الرابط اتنسخ. ابعتهوله.' => 'Link copied. Send it to them.',
    'حط السطر ده مرة واحدة في كل صفحات موقعك (قبل </body>). لما تبعت لعميل رابط متتبع (من صفحة العميل أو {site} في القوالب)، كل صفحة يفتحها بعد كده بتتسجل عنده، ولو فتح صفحة أسعار بيوصلك تنبيه "كلّمه دلوقتي". الزوار العاديين مابيتسجلوش.' => 'Add this line once to every page of your site (before </body>). When you send a lead a tracked link (from the lead page or {site} in templates), every page they open afterwards is logged on their record, and if they open a pricing page you get a "contact them now" alert. Regular visitors are not tracked.',
    'رابط موقعك' => 'Your site URL',
    'رقم الواتساب' => 'WhatsApp number',
