    'صفحة جديدة' => 'New page',
    'صفحة لكل حملة من غير موقع: عنوان، وصف، صورة، زرار واتساب، وفورم. حط لينكها في الإعلان أو البايو، وكل اللي يسجّل بيتعلّم باسم الحملة.' => 'A page per campaign with no website: title, text, image, WhatsApp button and a form. Put its link in the ad or bio, and every signup is tagged with the campaign.',
    'صوّر أو ارفع كارت' => 'Snap or upload a card',
    'صوّر الكارت من الموبايل. النص بيتقري في المتصفح (من غير ذكاء اصطناعي)، وانت تراجع البيانات قبل الحفظ.' => 'Snap the card on your phone. The text is read in the browser (no AI), and you review it before saving.',
