    'لينك لكل إعلان أو منشور. الرسالة بتتفتح فيها كود صغير زي #Ab12Cd3، ولما العميل يبعتها ويتضاف Lead بنعرف جه منين. والضغطات بتتعد.' => 'A link per ad or post. The message opens with a small code like #Ab12Cd3; when the customer sends it and becomes a lead, we know where they came from. Clicks are counted.',
    'لينك واتساب متتبع' => 'Tracked WhatsApp link',
