    'اتلغى اشتراكك. مش هتوصلك إيميلات تاني مننا.' => 'You are unsubscribed. You will not get more emails from us.',
    'احتمال الإغلاق لكل مرحلة وتوقع الإيراد في نافذة الإعدادات في صفحة العملاء، والنتيجة في تقارير المبيعات.' => 'Win probability per stage and revenue forecast are in the settings dialog on the Leads page, with results in Sales reports.',
    'اختار القيمة اللي تفضل في كل خانة. كل النشاطات والصفقات والخطط بتتنقل للعميل اللي هيفضل، والتاني بيتمسح.' => 'Pick the value to keep for each field. All activities, deals and plans move to the kept lead, and the other is deleted.',
    'اختيارات' => 'Choices',
    'ادمج' => 'Merge',
    'استخدم القالب' => 'Use the template',
    'افصل المبيعات عن التوظيف أو الشراكات. كل Pipeline ليه قايمته ولوحته في صفحة العملاء، والعميل تقدر تنقله من تفاصيله.' => 'Separate sales from hiring or partnerships. Each pipeline has its own list and board on the Leads page; move a lead from its details.',
    'الإعدادات دي بيعدّلها مدير العملاء بس.' => 'Only the CRM manager can edit these settings.',
    'الإيميلات والمهام مابتطلعش بالليل ولا يوم الإجازة. بتستنى لأول ساعة شغل.' => 'Emails and tasks are not sent at night or on days off. They wait for the next working hour.',
