    'حقول مخصصة' => 'Custom fields',
    'خانات زيادة بتظهر في تفاصيل كل عميل، زي الميزانية أو المنتج المطلوب أو المدينة. التاجات الأوتوماتيك تقدر تقراها.' => 'Extra fields shown in each lead\'s details, like budget, product or city. Auto-tags can read them.',
