    'سطر تحت (العنوان، الرقم الضريبي…)' => 'Footer line (address, tax number…)',
    'شكل موحد لكل إيميلات العملاء (من التفاصيل، والخطط، والإيميل الجماعي): لوجو ولون وتوقيع. كل إيميل فيه رابط إلغاء اشتراك، واللي يلغي مابيوصلوش حاجة تاني.' => 'One look for all customer emails (from details, plans and bulk): logo, color and signature. Every email has an unsubscribe link, and those who unsubscribe get nothing more.',
    'عملاءه هيرجعوا للمبيعات' => 'Its leads go back to Sales',
    'غيّر الأسماء والألوان، وضيف لحد 4 مراحل زيادة (بتتحط قبل "بقى عميل"). "جديد" و"بقى عميل" و"مش مناسب" أساسيين في التقارير فمابيتمسحوش.' => 'Change names and colors, and add up to 4 extra stages (placed before "Won"). "New", "Won" and "Lost" drive reports, so they cannot be removed.',
