    'لما تسجّل نتيجة مكالمة "مردّش" العدد ده، العميل بيتنقل لخطة تانية لوحده.' => 'When you log "No answer" this many times, the lead moves to another plan automatically.',
    'لو الخانة فيها الكلمة دي، العميل ياخد التاج ده لوحده أول ما يتضاف. مثلًا: الشركة فيها "مطعم" ← مطاعم، أو الرقم يبدأ بـ 966 ← السعودية.' => 'If the field contains this word, the lead gets this tag automatically when added. E.g. company contains "restaurant" → Restaurants, or phone starts with 966 → Saudi.',
    'لما رسالة أو تعليق جديد من العميل يتسجّل عليه (من زرار "ضيفه Lead" أو الجمع الأوتوماتيك) بعد ما الخطة بدأت، الخطة بتقف ويتعمل له مهمة "رد عليه". ردود الإيميل مش بتتقري.' => 'When a new message or comment from the lead is recorded on them (via "Add as lead" or auto-capture) after the plan started, the plan stops and a "Reply" task is created. Email replies are not read.',
