    'تعديل الميزانية لصاحب الشركة أو اللي عنده صلاحية الصرف بس.' => 'Only the owner or users with spend permission can change budgets.',
    'حسابات ثابتة من غير ذكاء اصطناعي: الحملة اللي صرفت ومجابتش عملاء أو عائدها سالب بتقل ميزانيتها %s%%، والفلوس دي بتروح للحملات اللي بتبيع بعائد عالي (على قد عائدها، ومن غير ما تزيد أكتر من %s%% في المرة). إجمالي الميزانية اليومية مابيزيدش. مفيش حاجة بتتنفذ غير لما توافق.' => 'Fixed rules, no AI: a campaign that spent without leads or with negative return is cut by %s%%, and that money goes to campaigns selling at a high return (by their return, at most +%s%% per step). The total daily budget never increases. Nothing runs until you approve.',
